// Issue 648: decode one row per listable entity under the GET /objects unions, as a client
// generated by swift-openapi-generator would, and print which members decode it.
// An anyOf union decodes into a struct with one optional per member; a oneOf union into
// an enum holding the first member that decodes. Run through ../run.sh.
import Foundation

let input = try JSONSerialization.jsonObject(
    with: Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[1]))) as! [String: Any]
let mapping = input["mapping"] as! [String: String]
let rows = input["rows"] as! [String: [String: Any]]

let decoder = JSONDecoder()
let rfc3339 = ISO8601DateFormatter()
rfc3339.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
decoder.dateDecodingStrategy = .custom { d in
    let text = try d.singleValueContainer().decode(String.self)
    guard let date = rfc3339.date(from: text) else {
        throw DecodingError.dataCorrupted(.init(codingPath: d.codingPath, debugDescription: "not RFC 3339: \(text)"))
    }
    return date
}

func members<T>(_ value: T) -> [String] {
    let mirror = Mirror(reflecting: value)
    if mirror.displayStyle == .enum {
        return mirror.children.compactMap { $0.label }
    }
    return mirror.children.compactMap { child -> String? in
        let inner = Mirror(reflecting: child.value)
        guard inner.displayStyle == .optional, let some = inner.children.first else { return nil }
        return String(describing: type(of: some.value)).components(separatedBy: ".").last
    }
}

var missing = 0
for entity in rows.keys.sorted() {
    var row = rows[entity]!["row"] as! [String: Any]
    let list = (try? decoder.decode(Components.Schemas.ListUnion.self,
                                    from: JSONSerialization.data(withJSONObject: row))).map(members) ?? []
    row["userfields"] = [String: Any]()
    let single = (try? decoder.decode(Components.Schemas.SingleUnion.self,
                                      from: JSONSerialization.data(withJSONObject: row))).map(members) ?? []
    var verdict = "-"
    if let own = mapping[entity] {
        let inSingle = entity == "locations_resolved" || single.contains(own)
        verdict = list.contains(own) && inSingle ? "own" : "MISSING \(own)"
        if verdict != "own" { missing += 1 }
    }
    print("\(entity)\t\(verdict)\tlist=\(list.isEmpty ? "none" : list.joined(separator: ","))\tsingle=\(single.isEmpty ? "none" : single.joined(separator: ","))")
}
print("mapped entities whose own member did not decode: \(missing)")
exit(missing == 0 ? 0 : 1)
